item.signature:
interface TenantFormData {
  tenant_id: string;
  name: string;
  description?: string;
  logo?: string;
  tool_type: 'servicedesk_plus' | 'jira' | 'none';
  servicedesk_url?: string;
  servicedesk_api_key?: string;
  jira_url?: string;
  jira_api_token?: string;
  jira_project_key?: string;
  webhook_signing_secret?: string;
  enhancement_preferences: {
    max_enhancement_length: number;
    include_monitoring: boolean;
    kb_timeout_seconds: number;
  };
  // NEW FIELDS TO ADD:
  byok_enabled: boolean;
  byok_openai_key?: string;
  byok_anthropic_key?: string;
  max_budget: number;
  alert_threshold: number;
  grace_threshold: number;
  budget_duration: '30d' | '60d' | '90d';
  is_active: boolean;
}

const tenantCreateSchema = z.object({
  tenant_id: z.string().min(1),
  name: z.string().min(1),
  description: z.string().optional(),
  logo: z.string().url().optional(),
  tool_type: z.enum(['servicedesk_plus', 'jira', 'none']),
  // Conditional tool fields...
  byok_enabled: z.boolean().default(false),
  byok_openai_key: z.string().startsWith('sk-').optional(),
  byok_anthropic_key: z.string().startsWith('sk-ant-').optional(),
  max_budget: z.number().min(0).max(10000).default(500),
  alert_threshold: z.number().int().min(50).max(100).default(80),
  grace_threshold: z.number().int().min(100).max(150).default(110),
  budget_duration: z.enum(['30d', '60d', '90d']).default('30d'),
  is_active: z.boolean().default(true),
  enhancement_preferences: z.object({...}),
}).refine(
  (data) => !data.byok_enabled || data.byok_openai_key || data.byok_anthropic_key,
  { message: "At least one API key required when BYOK enabled" }
).refine(
  (data) => data.grace_threshold > data.alert_threshold,
  { message: "Grace threshold must be greater than alert threshold" }
);

POST /api/v1/tenants
Content-Type: application/json
Authorization: Bearer {jwt_token}

Request Body: TenantFormData (all fields)
Response 201: { id: UUID, tenant_id: string, name: string, ... }
Response 400: { detail: string } or { field: "error message" }
Response 403: { detail: "Forbidden" }
Response 409: { detail: "Tenant ID already exists" }

PUT /api/v1/tenants/{id}
Content-Type: application/json
Authorization: Bearer {jwt_token}

Request Body: TenantFormData (all fields, partial updates not supported)
Response 200: { id: UUID, tenant_id: string, name: string, ... }
Response 400: { detail: string } or { field: "error message" }
Response 403: { detail: "Forbidden" }
Response 404: { detail: "Tenant not found" }
